using UnityEngine;

[RequireComponent(typeof(Terrain))]
public class TerrainGenerator13 : MonoBehaviour
{
    [SerializeField] int resolution = 256;
    [SerializeField] float maxHeight = 40f;
    [SerializeField] float scale = 25f;
    [SerializeField] int octaves = 4;

    void Start()
    {
        var data = GetComponent<Terrain>().terrainData;
        data.heightmapResolution = resolution + 1;
        data.size = new Vector3(resolution, maxHeight, resolution);
        int n = data.heightmapResolution;
        var heights = new float[n, n];
        for (int y = 0; y < n; y++)
        for (int x = 0; x < n; x++)
        {
            float h = 0f, amp = 1f, freq = 1f, total = 0f;
            for (int o = 0; o < octaves; o++)
            {
                h += Mathf.PerlinNoise(x * freq / scale, y * freq / scale) * amp;
                total += amp; amp *= 0.5f; freq *= 2f;
            }
            heights[y, x] = h / total;
        }
        data.SetHeights(0, 0, heights);
    }
}
