**Plan**
- A ConfirmDialog MonoBehaviour that builds a hidden modal (dim backdrop, message, Yes and No buttons) in code.
- A static Instance property finds or creates the dialog, so any script can call ConfirmDialog.Instance.Show(message, onYes, onNo).
- Clicking either button hides the dialog and then invokes the matching callback exactly once.

```csharp
using System;
using UnityEngine;
using UnityEngine.UIElements;

public class ConfirmDialog : MonoBehaviour
{
    private static ConfirmDialog instance;

    public static ConfirmDialog Instance
    {
        get
        {
            if (instance == null)
            {
                instance = FindObjectOfType<ConfirmDialog>();
                if (instance == null)
                {
                    GameObject go = new GameObject("ConfirmDialog");
                    instance = go.AddComponent<ConfirmDialog>();
                }
            }
            return instance;
        }
    }

    private VisualElement backdrop;
    private Label messageLabel;
    private Action yesCallback;
    private Action noCallback;

    private void Awake()
    {
        if (instance != null && instance != this)
        {
            Destroy(gameObject);
            return;
        }
        instance = this;
        Build();
    }

    private void Build()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            settings.sortingOrder = 100;
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;

        backdrop = new VisualElement();
        backdrop.style.position = Position.Absolute;
        backdrop.style.left = 0;
        backdrop.style.right = 0;
        backdrop.style.top = 0;
        backdrop.style.bottom = 0;
        backdrop.style.alignItems = Align.Center;
        backdrop.style.justifyContent = Justify.Center;
        backdrop.style.backgroundColor = new Color(0f, 0f, 0f, 0.6f);
        backdrop.style.display = DisplayStyle.None;
        root.Add(backdrop);

        VisualElement box = new VisualElement();
        box.style.width = 560;
        box.style.paddingTop = 30;
        box.style.paddingBottom = 30;
        box.style.paddingLeft = 30;
        box.style.paddingRight = 30;
        box.style.backgroundColor = new Color(0.14f, 0.16f, 0.22f, 1f);
        box.style.borderTopLeftRadius = 16;
        box.style.borderTopRightRadius = 16;
        box.style.borderBottomLeftRadius = 16;
        box.style.borderBottomRightRadius = 16;
        box.style.alignItems = Align.Center;
        backdrop.Add(box);

        messageLabel = new Label();
        messageLabel.style.fontSize = 32;
        messageLabel.style.color = Color.white;
        messageLabel.style.whiteSpace = WhiteSpace.Normal;
        messageLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
        messageLabel.style.marginBottom = 28;
        box.Add(messageLabel);

        VisualElement row = new VisualElement();
        row.style.flexDirection = FlexDirection.Row;
        box.Add(row);

        row.Add(MakeButton("Yes", new Color(0.2f, 0.6f, 0.3f, 1f), () => Resolve(true)));
        row.Add(MakeButton("No", new Color(0.7f, 0.25f, 0.25f, 1f), () => Resolve(false)));
    }

    public void Show(string message, Action onYes, Action onNo)
    {
        messageLabel.text = message;
        yesCallback = onYes;
        noCallback = onNo;
        backdrop.style.display = DisplayStyle.Flex;
    }

    private void Resolve(bool yes)
    {
        Action callback = yes ? yesCallback : noCallback;
        yesCallback = null;
        noCallback = null;
        backdrop.style.display = DisplayStyle.None;
        if (callback != null) callback();
    }

    private static Button MakeButton(string text, Color color, Action onClick)
    {
        Button button = new Button(onClick);
        button.text = text;
        button.style.width = 200;
        button.style.height = 60;
        button.style.fontSize = 28;
        button.style.marginLeft = 10;
        button.style.marginRight = 10;
        button.style.color = Color.white;
        button.style.backgroundColor = color;
        return button;
    }
}
```

Call `ConfirmDialog.Instance.Show("Delete save?", () => DeleteSave(), () => { })`. The singleton accessor creates the dialog GameObject on first use, and Awake builds the UI so Show works right away. Callbacks are cleared before they run, so each one fires once and a callback can safely open another dialog.

**Plan**
- Build a settings panel in code with two Slider controls (master volume, mouse sensitivity) and a Toggle (fullscreen).
- Load stored values from PlayerPrefs on enable and apply them immediately (AudioListener.volume, Screen.fullScreen).
- Save on every change and expose the sensitivity through a public static property so other scripts can read it.

```csharp
using System;
using UnityEngine;
using UnityEngine.UIElements;

public class SettingsMenuUI : MonoBehaviour
{
    private const string VolumeKey = "Settings.MasterVolume";
    private const string SensitivityKey = "Settings.MouseSensitivity";
    private const string FullscreenKey = "Settings.Fullscreen";

    public static float MouseSensitivity { get; private set; } = 2f;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        float volume = PlayerPrefs.GetFloat(VolumeKey, 1f);
        float sensitivity = PlayerPrefs.GetFloat(SensitivityKey, 2f);
        bool fullscreen = PlayerPrefs.GetInt(FullscreenKey, Screen.fullScreen ? 1 : 0) == 1;
        ApplyVolume(volume);
        MouseSensitivity = sensitivity;
        Screen.fullScreen = fullscreen;

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.style.flexGrow = 1;
        root.style.alignItems = Align.Center;
        root.style.justifyContent = Justify.Center;
        root.style.backgroundColor = new Color(0.08f, 0.09f, 0.13f, 1f);

        VisualElement card = new VisualElement();
        card.style.width = 640;
        card.style.paddingTop = 30;
        card.style.paddingBottom = 30;
        card.style.paddingLeft = 40;
        card.style.paddingRight = 40;
        card.style.backgroundColor = new Color(0.14f, 0.16f, 0.22f, 1f);
        card.style.borderTopLeftRadius = 16;
        card.style.borderTopRightRadius = 16;
        card.style.borderBottomLeftRadius = 16;
        card.style.borderBottomRightRadius = 16;
        root.Add(card);

        Label title = new Label("Settings");
        title.style.fontSize = 48;
        title.style.color = Color.white;
        title.style.marginBottom = 24;
        card.Add(title);

        Slider volumeSlider = MakeSlider(card, "Master Volume", 0f, 1f, volume, value =>
        {
            ApplyVolume(value);
            PlayerPrefs.SetFloat(VolumeKey, value);
            PlayerPrefs.Save();
        });
        volumeSlider.name = "VolumeSlider";

        MakeSlider(card, "Mouse Sensitivity", 0.1f, 10f, sensitivity, value =>
        {
            MouseSensitivity = value;
            PlayerPrefs.SetFloat(SensitivityKey, value);
            PlayerPrefs.Save();
        });

        Toggle fullscreenToggle = new Toggle("Fullscreen");
        fullscreenToggle.value = fullscreen;
        fullscreenToggle.style.fontSize = 26;
        fullscreenToggle.style.color = Color.white;
        fullscreenToggle.RegisterValueChangedCallback(evt =>
        {
            Screen.fullScreen = evt.newValue;
            PlayerPrefs.SetInt(FullscreenKey, evt.newValue ? 1 : 0);
            PlayerPrefs.Save();
        });
        card.Add(fullscreenToggle);
    }

    private static Slider MakeSlider(VisualElement parent, string labelText, float min, float max, float start, Action<float> onChange)
    {
        Label label = new Label(labelText + ": " + start.ToString("0.00"));
        label.style.fontSize = 26;
        label.style.color = Color.white;
        label.style.marginTop = 10;
        parent.Add(label);

        Slider slider = new Slider(min, max);
        slider.value = start;
        slider.style.marginBottom = 16;
        slider.RegisterValueChangedCallback(evt =>
        {
            label.text = labelText + ": " + evt.newValue.ToString("0.00");
            onChange(evt.newValue);
        });
        parent.Add(slider);
        return slider;
    }

    private static void ApplyVolume(float value)
    {
        AudioListener.volume = Mathf.Clamp01(value);
    }
}
```

Each slider is created by a helper that updates its own label, calls the supplied callback, and the callbacks write to PlayerPrefs and apply the setting immediately. On enable the saved values are read back and applied before the UI is built, so the controls start at the stored positions. Other scripts can read `SettingsMenuUI.MouseSensitivity` for their look code.

